/**
 * Data-driven product catalog.
 *
 * This module is the single source of truth for the Dr. Kent Homeopathy
 * website. It imports the generated `products.json` and `categories.json`
 * (which are also MongoDB-importable) and re-exports them in the shapes
 * expected by the existing UI components (ProductCard, ProductSlider,
 * ProductsCatalog, Home, ProductDescription).
 *
 * The JSON files are generated by `Backend/seedCatalogData.cjs` and can be
 * imported directly anywhere in the app:
 *
 *   import products from "./data/products.json";
 *
 * They are also compatible with MongoDB insertion via `mongoimport`.
 */

import rawProducts from "./products.json";
import rawCategories from "./categories.json";

/**
 * Map a raw JSON product to the shape expected by ProductCard / ProductSlider.
 * Keeps the original fields intact and adds UI-friendly aliases.
 */
const toCard = (p) => ({
  id: p.id,
  _id: p._id,
  name: p.product_name,
  price: p.discount_price,
  oldPrice: p.mrp_price,
  rating: p.rating,
  reviews: p.reviews,
  image: p.product_image,
  discount:
    p.discount_percentage > 0 ? `-${p.discount_percentage}%` : undefined,
  badge: p.bestSeller
    ? "Bestseller"
    : p.newArrival
      ? "New"
      : p.featured
        ? "Featured"
        : undefined,
  categoryTitle: p.category_name,
  brand: p.brand,
  isInStock: p.stock > 0,
  deliveryETA: "24 hrs",
  consultRequired: p.prescriptionRequired,
  shortDescription: p.short_description,
  longDescription: p.detailed_description,
  mrp: p.mrp_price,
  slug: p.slug,
  tags: p.tags,
  benefits: p.benefits,
  ingredients: p.ingredients,
  usage: p.usage,
  dosage: p.dosage,
  pack: p.pack,
  quantity: p.quantity,
  stock: p.stock,
  featured: p.featured,
  bestSeller: p.bestSeller,
  newArrival: p.newArrival,
  isKentProduct: p.isKentProduct,
  prescriptionRequired: p.prescriptionRequired,
});

const allProductCards = rawProducts.map(toCard);

/** Group products by their category name for quick lookup. */
const byCategory = rawProducts.reduce((acc, p) => {
  const key = p.category_name || "General Wellness";
  if (!acc[key]) acc[key] = [];
  acc[key].push(p);
  return acc;
}, {});

/**
 * Legacy category ids used by the Home page chips and ProductsCatalog URL
 * params (e.g. `/Products?category=diabetes`). New categories get their
 * slug as the id so the URL routing keeps working.
 */
const categoryIdMap = {
  Fever: "fever",
  "Cold & Cough": "cold-cough",
  Allergy: "allergy",
  "Skin Care": "skin",
  "Hair Care": "hair-care",
  "Digestive Care": "digest",
  "Women's Health": "women",
  "Children's Health": "children",
  "Joint & Muscle Pain": "pain",
  "Diabetes Care": "diabetes",
  "Kidney Care": "kidney",
  "Liver Care": "liver",
  Immunity: "immune",
  "Respiratory Care": "respiratory",
  "Stress & Sleep": "stress-sleep",
  "Heart Care": "heart",
  "Eye Care": "eye",
  "Dental Care": "dental",
  "General Wellness": "vitamins",
};

/**
 * Build the `allCategories` array consumed by Home and ProductsCatalog.
 * Each entry: { id, title, subtitle, products } where products are the
 * ProductCard-shaped objects.
 */
export const allCategories = rawCategories.map((cat) => ({
  id: categoryIdMap[cat.category_name] || cat.slug,
  title: cat.category_name,
  subtitle: cat.tagline || "Curated homeopathic remedies",
  description: cat.description || "",
  icon: cat.icon || "",
  image: cat.image || "",
  productCount: cat.productCount || 0,
  products: (byCategory[cat.category_name] || []).map(toCard),
}));

/** Featured products (used on the Home page hero slider). */
export const featuredProducts = allProductCards.filter((p) => p.featured);

/** Category-specific exports (kept for backward compatibility). */
export const adultsMedicine = (byCategory["General Wellness"] || []).map(toCard);
export const childrenMedicine = (byCategory["Children's Health"] || []).map(toCard);
export const diabetesCare = (byCategory["Diabetes Care"] || []).map(toCard);
export const heartCare = (byCategory["Heart Care"] || []).map(toCard);
export const womenWellness = (byCategory["Women's Health"] || []).map(toCard);
export const skinCare = (byCategory["Skin Care"] || []).map(toCard);
export const digestiveCare = (byCategory["Digestive Care"] || []).map(toCard);
export const immunityBoosters = (byCategory["Immunity"] || []).map(toCard);
export const painRelief = (byCategory["Joint & Muscle Pain"] || []).map(toCard);
export const vitaminsSupplements = (byCategory["General Wellness"] || []).map(toCard);

/** Raw JSON exports for direct data-driven consumption. */
export const products = rawProducts;
export const categories = rawCategories;

export default allProductCards;

